#!/usr/bin/env python3
"""gen_utci.py (v91.17.101, N1) -- writes server/api/utci.mjs: the UTCI 6th-order regression polynomial (Broede et al. 2012,
the operational UTCI approximation) ported line for line from pythermalcomfort 4.6 (MIT licence, (c) Federico Tartarini and
contributors), so the server and the browser compute the same number. Run: python3 scripts/gen/gen_utci.py (needs pythermalcomfort)."""
import inspect, re, os, json, pythermalcomfort
from pythermalcomfort.models import utci as U
src = inspect.getsource(inspect.getmodule(U)._utci_optimized)
body = src[src.index('return (') + len('return ('): src.rindex(')')]
body = re.sub(r'\(\s*(-?[\d.]+)\s*\*\s*\(10 \*\* \((-?\d+)\)\)\s*\)', lambda m: '(%se%s)' % (m.group(1), m.group(2)), body)
body = re.sub(r'\(10 \*\* \((-?\d+)\)\)', lambda m: '1e%s' % m.group(1), body)
assert '**' not in body, body[:400]
body = ' '.join(body.split())
here = os.path.dirname(os.path.abspath(__file__)); CF = json.load(open(os.path.join(here, '..', '..', 'data', 'utci.json'))); out = os.path.join(here, '..', '..', 'server', 'api', 'utci.mjs')
JS = """/* v91.17.101 · N1 · UNIVERSAL THERMAL CLIMATE INDEX. GENERATED by scripts/gen/gen_utci.py - do not edit by hand.
   The UTCI regression polynomial (Broede P., Jendritzky G., Fiala D., Havenith G. 2012, Int J Biometeorol 56:481-494; the operational
   approximation of the Fiala multi-node model) ported line for line from pythermalcomfort %s (MIT licence, (c) F. Tartarini and
   contributors). Valid for -50 < Ta < 50 C, -30 < Tmrt - Ta < 70 C, 0.5 < wind(10 m) < 17 m/s, 0 <= RH <= 100 %, vapour pressure <= 5 kPa (v91.17.283.8); outside it the function refuses (null).
   The build inlines this file into the page between the UTCI markers, so server and browser compute the same value. */
/*__UTCI_BEGIN__*/
function agnUtciEs(ta) { const g = [-2836.5744, -6028.076559, 19.54263612, -0.02737830188, 0.000016261698, 7.0229056e-10, -1.8680009e-13]; const tk = ta + 273.15; let es = 2.7150305 * Math.log(tk); for (let i = 0; i < g.length; i++) es += g[i] * Math.pow(tk, i - 2); return Math.exp(es) * 0.01; }
function agnUtci(tdb, tr, v, rh) {
  if (![tdb, tr, v, rh].every((x) => x != null && isFinite(+x))) return null;
  tdb = +tdb; tr = +tr; v = Math.max(0.5, +v); rh = +rh;   /* calm air: the model's floor is 0.5 m/s at 10 m (the reference condition) */
  if (tdb <= -50 || tdb >= 50 || tr - tdb <= -30 || tr - tdb >= 70 || v >= 17) return null;
  if (!(rh >= 0 && rh <= 100)) return null;   /* v91.17.283.8 · audit 13 · relative humidity is 0-100 %: outside it the input is not physical (not assessed) */
  const pa = agnUtciEs(tdb) * (rh / 100) / 10, delta_t_tr = tr - tdb;
  if (pa > 5) return null;   /* v91.17.283.8 · audit 13 · the polynomial's domain (Broede et al. 2012): water vapour pressure up to 5 kPa */
  const u = (%s);
  return Math.round(u * 10) / 10;
}
/* mean radiant temperature of a standing person OUTDOORS, from the forecast's radiation (an estimate, not measured):
     Tmrt^4 = Ta^4 + (a_k / (e_p * sigma)) * (fp * I_normal + 0.5 * D + 0.5 * albedo * G)
   a_k 0.7 (absorbed short-wave), e_p 0.97, fp the projected-area factor of a standing person at sun elevation b (Fanger 1970:
   0.308 cos(b (1 - b^2/48402)), b in degrees), D diffuse, G global, albedo 0.25 (dry ground). The long-wave field is taken as the
   air temperature (no sky / ground long-wave in the feed): at night under clear sky this overstates Tmrt by a few degrees, by day the
   short-wave term dominates. In SHADE, Tmrt = Ta. */
function agnTmrt(ta, ghi, dhi, sunElevDeg, albedo) {
  if (ta == null || !isFinite(+ta)) return null; ta = +ta;
  if (ghi == null || !isFinite(+ghi) || sunElevDeg == null || !isFinite(+sunElevDeg) || sunElevDeg <= 0 || ghi <= 0) return ta;
  const b = +sunElevDeg, sinb = Math.sin(b * Math.PI / 180), D = (dhi != null && isFinite(+dhi)) ? Math.min(+dhi, +ghi) : 0.3 * ghi;
  const In = sinb > 0.05 ? Math.max(0, (ghi - D) / sinb) : 0, fp = 0.308 * Math.cos(b * (1 - b * b / 48402) * Math.PI / 180), al = albedo == null ? %s : albedo;
  const sw = fp * In + 0.5 * D + 0.5 * al * ghi, s = 5.67e-8;
  return Math.round((Math.pow(Math.pow(ta + 273.15, 4) + %s * sw / (%s * s), 0.25) - 273.15) * 10) / 10;
}
/* solar elevation (degrees) at lat/lon for a UTC instant (NOAA approximate equations, within ~0.5 degree) */
function agnSunElev(lat, lon, tMs) {
  const d = new Date(tMs), doy = Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 0)) / 864e5);
  const h = d.getUTCHours() + d.getUTCMinutes() / 60, g = 2 * Math.PI / 365 * (doy - 1 + (h - 12) / 24);
  const eq = 229.18 * (0.000075 + 0.001868 * Math.cos(g) - 0.032077 * Math.sin(g) - 0.014615 * Math.cos(2 * g) - 0.040849 * Math.sin(2 * g));
  const dec = 0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g) - 0.006758 * Math.cos(2 * g) + 0.000907 * Math.sin(2 * g) - 0.002697 * Math.cos(3 * g) + 0.00148 * Math.sin(3 * g);
  const ha = ((h * 60 + eq + 4 * lon) / 4 - 180) * Math.PI / 180, la = lat * Math.PI / 180;
  return Math.asin(Math.sin(la) * Math.sin(dec) + Math.cos(la) * Math.cos(dec) * Math.cos(ha)) * 180 / Math.PI;
}
/* the ten UTCI assessment classes (Blazejczyk et al. 2013, Geogr Pol 86:5-10), upper bounds in C */
const AGN_UTCI_CLASSES = %s.map((c) => [c[0] == null ? Infinity : c[0], c[1]]);   /* from data/utci.json */
const AGN_UTCI_AGN_MAP = %s;   /* from data/utci.json agnMapping: an AGN convention, not a published threshold */
function agnUtciAgnScore(u) { if (u == null || !isFinite(u)) return null; const P = AGN_UTCI_AGN_MAP.points; if (u <= P[0][0]) return 0; for (let i = 1; i < P.length; i++) if (u <= P[i][0]) return Math.round(P[i - 1][1] + (u - P[i - 1][0]) / (P[i][0] - P[i - 1][0]) * (P[i][1] - P[i - 1][1])); return 100; }
const AGN_UTCI_COLD_MAP = %s;   /* from data/utci.json agnColdMapping (v91.17.111): the cold-stress classes, one AGN level each */
/* a value exactly on a class bound belongs to the warmer class, as in the class table (upper bounds exclusive: -13.0 is moderate, not
   strong, cold stress), so it scores one point under that band edge */
function agnUtciColdScore(u) { if (u == null || !isFinite(u)) return null; const P = AGN_UTCI_COLD_MAP.points; if (u >= P[0][0]) return 0; for (let i = 1; i < P.length; i++) { if (u === P[i][0]) return P[i][1] - 1; if (u > P[i][0]) return Math.min(P[i][1] - 1, Math.round(P[i - 1][1] + (P[i - 1][0] - u) / (P[i - 1][0] - P[i][0]) * (P[i][1] - P[i - 1][1]))); } return 100; }
function agnUtciClass(u) { if (u == null || !isFinite(u)) return null; for (const [t, n] of AGN_UTCI_CLASSES) if (u < t) return n; return 'Extreme heat stress'; }
/*__UTCI_END__*/
export { agnUtci as utci, agnTmrt as tmrt, agnSunElev as sunElev, agnUtciClass as utciClass, AGN_UTCI_CLASSES as UTCI_CLASSES, agnUtciAgnScore as utciAgnScore, AGN_UTCI_AGN_MAP as UTCI_AGN_MAP, agnUtciColdScore as utciColdScore, AGN_UTCI_COLD_MAP as UTCI_COLD_MAP };
""" % (pythermalcomfort.__version__, body, CF["tmrt"]["albedo"], CF["tmrt"]["absorbedShortwave"], CF["tmrt"]["emissivity"], json.dumps(CF["classes"]), json.dumps({"version": CF["agnMapping"]["version"], "points": CF["agnMapping"]["points"]}), json.dumps({"version": CF["agnColdMapping"]["version"], "points": CF["agnColdMapping"]["points"]}))
open(out, 'w').write(JS); print('wrote', out, len(JS), 'bytes')
